  const [dirty, setDirty] = useState(false), [review, setReview] = useState(!!pending), [unit, setUnit] = useState<UnitChoice | null>(null), [baseVersion, setBaseVersion] = useState(Number(pending?.expectedVersion ?? value?.version ?? 0)), [latestReviewed, setLatestReviewed] = useState(false);
