  const [draft, setDraft] = useState<ConversionDraft>(() => ({ mode: previous?.contactId ? "existing" : "prepare", startsOn: String(previous?.startsOn || prospect.desiredMoveIn?.slice(0, 10) || ""), endsOn: String(previous?.endsOn || ""), monthlyRent: String(previous?.monthlyRent || ""), rentDueDay: String(previous?.rentDueDay ?? "1"), graceDays: String(previous?.graceDays ?? "0"), paymentInstructions: String(previous?.paymentInstructions || "") }));
